import {centerInventory} from './center-inventory.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=value=>Math.max(0,Number(value)||0).toLocaleString();
const label=value=>String(value??'').replace(/[-_]/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
const routeLink=(path,text,className='')=>`<a class="${className}" href="#/${esc(path)}">${text}</a>`;
const button=(text,action,payload={},color='blue',extra='')=>`<button type="button" class="${color}-button" data-action="${esc(action)}" data-payload="${esc(JSON.stringify(payload))}" ${extra}>${text}</button>`;
const blank=(title,text='')=>`<div class="empty-state"><strong>${esc(title)}</strong>${esc(text)}</div>`;
const typeClass=value=>'type-'+String(value??'Normal').toLowerCase().replace(/[^a-z]/g,'');
const formName=p=>p.shiny===2?'Shadow':p.shiny===1?'Shiny':'Regular';
const typeOptions=selected=>['','Normal','Grass','Poison','Fire','Water','Flying','Bug','Ghost','Steel','Rock','Electric','Ice','Fighting','Ground','Dragon','Dark','Psychic'].map(t=>`<option value="${t}" ${t===selected?'selected':''}>${t||'All types'}</option>`).join('');
export function centerSpriteKey(p,manifest){const id=String(p.speciesId).padStart(3,'0'),variant=p.shiny===2?'ss':p.shiny===1?'s':null,key=variant?`poke_${variant}_${id}`:'';return manifest[key]?key:manifest[`poke_${id}`]?`poke_${id}`:'poke_1010';}

/** HTML interface for the local PokéCenter. Domain mutations are delegated to
 * CenterService so the website and future transports share the same rules. */
export class CenterUI{
 constructor({data,sprites,icons={},service,root,dialog}){Object.assign(this,{data,sprites,icons,service,root,dialog});this.filters={query:'',form:'',type:'',sort:'number',direction:'asc',page:1};this.selection=new Set();this.pages={};this.pickers=new Map();this.busy=false;this.lastResult=null;this.spinResult=null;}
 get profile(){return this.service.profile;}
 get state(){return this.service.state;}
 get bank(){return this.service.bank;}
 get active(){return this.service.active??this.bank.active;}
 get wallet(){return this.service.wallet??this.state.wallets?.[this.active]??{};}
 get route(){try{return (location.hash.replace(/^#\/?/,'')||'home').split('?')[0].split('/').map(decodeURIComponent);}catch{return ['home'];}}
 start(){window.addEventListener('hashchange',()=>{this.selection.clear();this.pages={};this.filters.page=1;this.render();window.scrollTo({top:0,behavior:'instant'});this.settleDue();});this.root.addEventListener('toggle',e=>{if(e.target.matches('.nav-dropdown')&&e.target.open)this.root.querySelectorAll('.nav-dropdown').forEach(menu=>{if(menu!==e.target)menu.open=false;});},true);this.root.addEventListener('click',e=>this.click(e));this.root.addEventListener('submit',e=>this.submit(e));this.root.addEventListener('change',e=>this.change(e));this.dialog.addEventListener('click',e=>this.click(e));this.dialog.addEventListener('submit',e=>this.submit(e));this.dialog.addEventListener('change',e=>this.change(e));this.dialog.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-picker-query]')){e.preventDefault();this.filterPicker(e.target.closest('[data-picker]').dataset.picker);}});this.dialog.addEventListener('close',()=>{if(!this.dialog.open){this.pickers.clear();this.dialog.replaceChildren();}});window.addEventListener('focus',()=>this.refresh());this.render();this.settleDue();this.refreshTimer=setInterval(()=>this.tickGiveaway(),15000);}
 async refresh(){if(this.busy)return;this.busy=true;this.lockControls(true);try{const before=JSON.stringify(this.bank);await this.service.refresh();const redraw=!!this.conflict||before!==JSON.stringify(this.bank)||this.renderedDisplayContext!==this.displayContext();this.conflict=null;if(redraw)this.render();else this.updateGiveawayCountdown();}catch(error){this.showConflict({error});}finally{this.busy=false;this.lockControls(false);}await this.settleDue();}
 displayContext(){const {locale,timeZone}=new Intl.DateTimeFormat().resolvedOptions();return JSON.stringify([new Date().toISOString().slice(0,10),locale,timeZone]);}
 lockControls(disabled){document.querySelectorAll('[data-action],form button').forEach(button=>{button.disabled=disabled||button.dataset.locked==='true';});}
 showConflict({error}){this.conflict=error?.message??'The account changed in another window. Refresh before saving.';this.render();this.toast(this.conflict,true);}
 async settleDue(){if(this.busy||this.dialog.open||!this.profile||this.conflict)return;const time=this.service.clock?.()??Date.now();if(!(this.state.giveaways??[]).some(g=>g.status==='open'&&g.endsAt<=time))return;this.busy=true;this.lockControls(true);try{await this.service.perform('settleGiveaways',{});this.render();}catch(error){this.showConflict({error});}finally{this.busy=false;this.lockControls(false);}}
 toast(message,error=false){const node=document.querySelector('#center-toast');node.textContent=message;node.style.background=error?'#96342d':'#174b6a';node.classList.add('visible');clearTimeout(this.toastTimer);this.toastTimer=setTimeout(()=>node.classList.remove('visible'),4500);}
 async action(type,payload={},options={}){if(this.busy)return;this.busy=true;document.querySelectorAll('[data-action],form button').forEach(b=>b.disabled=true);try{const result=await this.service.perform(type,payload);this.lastResult=result;this.dialog.close();if(options.route)location.hash='/'+options.route;this.render();if(result?.message)this.toast(result.message);else if(result?.reward?.amount!==undefined)this.toast(`You received ${money(result.reward.amount)} ${this.currencyName(result.reward.currency)}!`);else if(result?.reward?.credits!==undefined)this.toast(`You received ${money(result.reward.credits)} Credits and ${money(result.reward.casino)} Casino Coins!`);else if(result?.pokemon&&['adopt','buyReward','mysteryGift','giftCode'].includes(type))this.toast(`${this.pokemonName(result.pokemon)} is ready on your Pick Up page.`);else this.toast(options.message??'Your changes have been saved.');return result;}catch(error){this.render();this.toast(error.message,true);const el=this.dialog.querySelector('.inline-error');if(this.dialog.open&&el)el.textContent=error.message;return null;}finally{this.busy=false;document.querySelectorAll('[data-action],form button').forEach(b=>{if(b.dataset.locked!=='true')b.disabled=false;});}}
 sprite(p,size=88){const asset=this.sprites[centerSpriteKey(p,this.sprites)];if(!asset)return '';const scale=Math.min(size/asset.frameWidth,size/asset.frameHeight,2.2),w=asset.frameWidth*scale,h=asset.frameHeight*scale;return `<span class="center-sprite ${size<60?'small':''}" aria-hidden="true"><span style="width:${w}px;height:${h}px;background-image:url('assets/${esc(asset.file)}');background-size:${w*asset.frameCount}px ${h}px"></span></span>`;}
 date(value){if(!value)return '';const d=new Date(value),s=this.state.settings??{},parts={MM:String(d.getMonth()+1).padStart(2,'0'),DD:String(d.getDate()).padStart(2,'0'),YYYY:String(d.getFullYear())},hour12=s.timeFormat==='12';this.timeFormatters??=new Map();if(!this.timeFormatters.has(hour12))this.timeFormatters.set(hour12,new Intl.DateTimeFormat(undefined,{hour:'2-digit',minute:'2-digit',hour12}));return (s.dateFormat??'MM.DD.YYYY').replace(/YYYY|MM|DD/g,k=>parts[k])+' '+(Number.isNaN(d.getTime())?d.toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit',hour12}):this.timeFormatters.get(hour12).format(d));}
 icon(key,size=24,title=''){const frame=this.icons[key];if(!frame)return title?`<span class="type-badge ${typeClass(title)}">${esc(title)}</span>`:'';const scale=size/frame.width;return `<span class="center-icon" ${title?`role="img" aria-label="${esc(title)}" title="${esc(title)}"`:'aria-hidden="true"'} style="width:${frame.width*scale}px;height:${frame.height*scale}px;background-image:url('assets/center/icons.webp');background-position:${frame.x*scale}px ${frame.y*scale}px;background-size:${416*scale}px ${408*scale}px"></span>`;}
 avatarKey(avatar){const key=(avatar?.gender==='girl'?'g':'b')+'_'+(avatar?.style??1);return this.icons[key]?key:avatar?.gender==='girl'&&[9,12,15].includes(avatar?.style)?'b_'+avatar.style:avatar?.gender==='girl'?'g_1':'b_1';}
 avatarStyles(gender,selected=1){const names=['Regular','Raikou Hat','Entei Hat','Suicune Hat','Shiny Geodude Hat','Bug Catcher','Team Rocket','Camper','Celebi Hoodie','Cubone Hat','Spiritomb Mask','Haunter Costume','Gengar Costume','Gastly Mask','Duskull Costume','Alakazam Costume','Delibird Costume','Elf Costume','Bulbasaur Hat'];return names.map((name,i)=>{const style=i+1,current=this.profile?.avatar,retained=current?.style===style&&current?.gender===gender,locked=!retained&&(style===3&&(this.profile?.achievements?.[4]??0)<2||style===4&&(this.profile?.achievements?.[5]??0)<2);return `<option value="${style}" ${style===selected?'selected':''} ${locked?'disabled':''}>${esc(name)}${locked?' · Earn in PTD 1':''}</option>`;}).join('');}
 currencyName(currency){return currency==='icu'||currency==='credits'?'Credits':currency==='casino'?'Casino Coins':'Pokédollars';}
 slotSymbol(symbol){return this.icon(symbol,40,({seven:'Seven',bar:'Bar',cherry:'Cherry',pokeballSlot:'Poké Ball',arbok:'Arbok',jiggly:'Jigglypuff',voltorb:'Voltorb'}[symbol]??symbol));}
 pokemonName(p){return p.nickname||this.data.species[p.speciesId]?.name||'Unknown Pokémon';}
 trainer(slot){return this.bank.slots[slot]?.trainer??'Trainer '+(Number(slot)+1);}
 card(p,{actions='',select=false,meta='',extra=''}={}){const species=this.data.species[p.speciesId]??{},types=species.types??[],tag=this.state.tags?.[p.uid]??(String(p.myTag??'').toLowerCase()==='h'?'hacked':null);return `<article class="pokemon-card ${p.shiny===1?'shiny':p.shiny===2?'shadow':''} ${this.selection.has(p.uid)?'card-selected':''}" data-pokemon-card="${esc(p.uid)}">${select?`<label class="card-select"><input type="checkbox" data-select-pokemon="${esc(p.uid)}" aria-label="Select ${esc(this.pokemonName(p))}" ${this.selection.has(p.uid)?'checked':''}></label>`:''}<div class="name-tab">${esc(this.pokemonName(p))}</div><div class="card-types">${types.map(t=>this.icon('t'+String(t).toLowerCase(),22,t)).join('')}</div><div class="card-body">${this.sprite(p,64)}<div><div class="card-level">Level ${p.level}</div><div class="card-moves">${(p.moves??[]).map(id=>{const m=this.data.moves[id];return `<span class="move-chip ${m?.typeId===18?'type-shadow':typeClass(m?.type)}" title="${esc(m?.description??'')}">${esc(m?.name??'Move '+id)}</span>`;}).join('')}</div></div></div>${tag||meta?`<div class="card-meta">${tag?`Tag: ${esc(typeof tag==='object'?tag.name??tag.type:tag)}`:''}${meta?`${tag?'<br>':''}${meta}`:''}</div>`:''}${extra}${actions?`<div class="card-actions">${actions}</div>`:''}</article>`;}
 heading(title,right=''){return `<h1 class="page-heading"><span>PTD: ${esc(title)}</span>${right}</h1>`;}
 tabs(entries,current){return `<div class="page-tabs">${entries.map(([path,title])=>routeLink(path,esc(title),current===path?'active':'')).join('')}</div>`;}
 profileOptions(selected=this.active){return this.bank.slots.flatMap((p,i)=>p?[`<option value="${i}" ${Number(selected)===i?'selected':''}>Profile ${i+1}: ${esc(p.trainer)}</option>`]:[]).join('');}
 speciesOptions(selected='',all='Any Pokémon'){return `<option value="">${esc(all)}</option>`+Object.values(this.data.species).map(s=>`<option value="${s.id}" ${String(selected)===String(s.id)?'selected':''}>#${String(s.id).padStart(3,'0')} ${esc(s.name)}</option>`).join('');}
 profileRequired(){return this.heading('Choose a profile')+blank('Welcome to the PokéCenter','Choose or create a local profile to manage Pokémon, trade, and collect rewards.')+this.profilesGrid();}
 render(){if(this.pageOwner!==this.active){this.pages={};this.filters.page=1;this.selection.clear();this.pageOwner=this.active;}this.renderedDisplayContext=this.displayContext();this.timeFormatters=new Map();const prefs=this.state.settings??{};document.body.classList.toggle('dark-theme',!!prefs.darkMode);document.body.classList.toggle('compact-cards',!!prefs.oldCards);document.body.classList.toggle('plain-moves',prefs.colorMoves===false);document.body.classList.toggle('plain-actions',prefs.colorActions===false);const [page,id]=this.route;const unread=(this.state.notifications??[]).filter(n=>Number(n.owner)===this.active&&!n.read).length;this.root.innerHTML=`<header class="center-top"><div class="center-top-inner"><a class="center-logo" href="#/home" aria-label="Pokémon Tower Defense PokéCenter home"><img src="assets/center/logo.webp" width="450" height="150" alt="Pokémon Tower Defense PokéCenter"></a><div class="center-top-meta"><span>Local PokéCenter · Saved on this device</span><a href="./">← Play Pokémon Tower Defense</a></div></div></header><nav class="center-nav" aria-label="Main navigation"><div class="center-nav-inner">${this.navigation(page,unread)}</div></nav><div class="center-shell"><aside class="center-sidebar ${this.sidebarOpen?'open':''}"><div class="center-sidebar-title"><button data-ui="sidebar" aria-expanded="${!!this.sidebarOpen}">${this.profile?this.icon(this.avatarKey(this.profile.avatar),32):''}<span>${esc(this.profile?.trainer??'Trainer Account')}</span><span aria-hidden="true">▾</span></button></div><div class="center-sidebar-body">${this.sidebar()}</div></aside><main class="center-main" id="center-main">${this.conflict?`<div class="notice error" role="alert">${esc(this.conflict)} ${button('Refresh Account','ui:refresh',{},'blue')}</div>`:''}${!this.profile&&!['home','settings'].includes(page)?this.profileRequired():this.page(page,id)}</main></div><footer class="center-footer">Pokémon Tower Defense by Sam Otero and Dan Connelly.<br>Pokémon © Nintendo, Creatures, and GAME FREAK. · Local PokéCenter</footer>`;document.title=`${label(page)} — PTD PokéCenter`;this.lockControls(this.busy);if(page==='settings'&&id)requestAnimationFrame(()=>document.getElementById('center-'+id)?.scrollIntoView({block:'start'}));}
 navigation(page,unread){const groups=[['Stores',[['adoption','Adoption Center'],['trainer-adoptions','Trainer Adoptions']]],['Convert',[['conversion','Shiny / Shadow Pokémon'],['tags','Remove Hacked Tags'],['transfer','Transfer Pokémon']]],['My Pokémons',[['collection','Your Pokémon'],['dex','Pokédex'],['inventory','Your Items']]],['Giveaways',[['giveaways','Active Giveaways'],['my-giveaways','Your Giveaways'],['past-giveaways','Concluded Giveaways']]],['Trading Center',[['trades','Latest Trades'],['search','Search Trades'],['my-trades','Your Trades'],['offers','Your Offers']]],['Account',[['settings/nickname','Change Nickname'],['settings/avatar','Change Avatar'],['settings/backup','Account Backups'],['home','Change Profile'],['notifications','Notifications'+(unread?` (${unread})`:'')]]]];const group=(title,entries)=>`<details class="nav-dropdown ${entries.some(([path])=>path.split('/')[0]===page)?'active':''}"><summary>${esc(title)}</summary><div class="nav-dropdown-menu">${entries.map(([path,text])=>routeLink(path,esc(text))).join('')}</div></details>`;return routeLink('settings','<span aria-hidden="true">⚙</span><span class="sr-only">Settings</span>',page==='settings'?'active':'')+routeLink('home','Home',page==='home'?'active':'')+group(...groups[0])+group(...groups[1])+routeLink('daily','Daily Gift',page==='daily'?'active':'')+routeLink('game-corner','Game Corner',page==='game-corner'?'active':'')+groups.slice(2).map(g=>group(...g)).join('');}
 sidebar(){const p=this.profile,inbox=(this.state.inbox??[]).filter(x=>Number(x.owner)===this.active).length;return `${p?`<div class="sidebar-badges" aria-label="${p.badges??0} badges">${Array.from({length:8},(_,i)=>`<span class="source-badge ${(p.badges??0)>i?'earned':''}" style="background-position:${-16*i}px 0" title="Badge ${i+1}${(p.badges??0)>i?' earned':''}"></span>`).join('')}</div><dl class="profile-stats"><dt>Version</dt><dd>${p.gameVersion===2?'Blue':'Red'}</dd><dt>Credits</dt><dd>${money(this.wallet.credits)}</dd><dt>Casino Coins</dt><dd>${money(this.wallet.casino)}</dd><dt>Pokédollars</dt><dd>₽ ${money(p.money)}</dd><dt>Pokémon</dt><dd>${p.pokemon.length}</dd><dt>Story Progress</dt><dd>${(p.completed??[]).length} stages</dd><dt>Challenge Progress</dt><dd>${p.challengeCompleted??0} completed</dd></dl>`:'<p>Select a profile to open your trainer account.</p>'}<div class="side-links">${routeLink('home','Change Profile')}${p?routeLink('pickup',`Pick Up Pokémon${inbox?` (${inbox})`:''}`):''}${routeLink('account','Your Account')}${routeLink('settings','Account Settings')}</div>`;}
 account(){return this.heading('Your Account')+`<div class="account-links">${[['collection','Your Pokémon','Sort, rename and manage your collection.'],['my-trades','Your Trades','Create, edit and recall your listings.'],['offers','Your Offers','Review the offers you have made.'],['pickup','Pick Up Pokémon','Receive completed trades and prizes.'],['inventory','Your Items','View your PTD 1 evolution items.'],['dex','Pokédex','View your collection record.'],['conversion','Shiny / Shadow Pokémon','Convert regular Pokémon with earned currency.'],['tags','Pokémon Tags','Remove hacked tags from your Pokémon.'],['transfer','Transfer Pokémon','One-way local PTD 2 and PTD 3 archives.'],['my-giveaways','Your Giveaways','Manage prizes and giveaway entries.'],['settings','Account Settings','Choose an avatar, preferences, or account backup.']].map(([path,title,description])=>`<article class="details-box"><h3>${routeLink(path,esc(title))}</h3><p>${esc(description)}</p></article>`).join('')}</div>`;}

 page(page,id){switch(page){case'home':return this.home();case'account':return this.account();case'collection':return this.collection();case'pickup':return this.pickup();case'trades':case'search':case'my-trades':case'offers':return this.trades(page);case'trade':return this.trade(id);case'adoption':case'trainer-adoptions':return this.adoption(page);case'daily':return this.daily();case'game-corner':return this.gameCorner();case'conversion':case'tags':return this.conversion(page);case'giveaways':case'my-giveaways':case'past-giveaways':return this.giveaways(page);case'giveaway':return this.giveaway(id);case'inventory':return this.inventory();case'dex':return this.dex();case'notifications':return this.notifications();case'settings':return this.settings();case'transfer':return this.transfer();default:return this.heading('Page not found')+routeLink('home','Return to your account');}}
 profilesGrid(){return `<div class="profile-grid">${this.bank.slots.map((p,i)=>`<article class="profile-card ${p?p.gameVersion===2?'blue':'':'empty'}"><h3>Profile ${i+1}${i===this.active&&p?' · Selected':''}</h3>${p?`<h3 style="background:none;color:#155d92;margin:0;padding:0;font-size:18px">${esc(p.trainer)}</h3><p>${p.gameVersion===2?'Blue':'Red'} Version · ${p.badges??0} badges<br>${p.pokemon.length} Pokémon · ₽ ${money(p.money)}</p><div class="profile-party">${p.party.filter(Boolean).map(uid=>p.pokemon.find(v=>v.uid===uid)).filter(Boolean).map(p=>this.sprite(p,48)).join('')}</div>${button('Select Profile','selectProfile',{slot:i},'blue')}`:`<p>Start a new local adventure.</p>${button('Create Profile','ui:create-profile',{slot:i},'green')}`}</article>`).join('')}</div>`;}
 home(){return this.heading('PokéCenter Home')+`<p>Welcome${this.profile?`, <strong>${esc(this.profile.trainer)}</strong>`:''}! Manage your Pokémon, find a trade, and collect your daily rewards.</p>`+(this.state.settings?.announcements!==false?'<div class="notice">Welcome to your local PokéCenter. The three profiles are your trainers for trades and giveaways; progress is shared with the game.</div>':'')+this.profilesGrid()+(this.profile?`<div class="stat-tiles"><div class="stat-tile"><strong>${money(this.wallet.credits)}</strong>Credits</div><div class="stat-tile"><strong>${money(this.wallet.casino)}</strong>Casino Coins</div><div class="stat-tile"><strong>${(this.state.inbox??[]).filter(x=>Number(x.owner)===this.active&&!x.claimed).length}</strong>Pokémon to pick up</div></div><div class="actions">${routeLink('pickup','Pick Up Pokémon','green-button')}${routeLink('daily','Get Your Daily Gift','blue-button')}${routeLink('trades','Browse Latest Trades','blue-button')}</div>`:'');}
 filterToolbar(){const f=this.filters;return `<form class="toolbar" data-form="filter"><label>Find Pokémon<input name="query" value="${esc(f.query)}" placeholder="Name or Pokédex number"></label><label>Appearance<select name="form">${[['','All Pokémon'],['0','Regular'],['1','Shiny'],['2','Shadow']].map(([v,t])=>`<option value="${v}" ${f.form===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Type<select name="type">${typeOptions(f.type)}</select></label><label>Sort by<select name="sort">${['number','name','level','received'].map(v=>`<option value="${v}" ${f.sort===v?'selected':''}>${label(v)}</option>`).join('')}</select></label><label>Order<select name="direction"><option value="asc" ${f.direction==='asc'?'selected':''}>Ascending</option><option value="desc" ${f.direction==='desc'?'selected':''}>Descending</option></select></label><button class="blue-button" type="submit">Apply</button></form>`;}
 filterPokemon(values){const f=this.filters;let out=values.filter(p=>(!f.query||`${p.speciesId} ${this.pokemonName(p)} ${this.data.species[p.speciesId]?.name}`.toLowerCase().includes(f.query.toLowerCase()))&&(f.form===''||(p.shiny??0)===Number(f.form))&&(!f.type||this.data.species[p.speciesId]?.types.includes(f.type)));if(f.sort!=='received')out.sort((a,b)=>(f.sort==='name'?this.pokemonName(a).localeCompare(this.pokemonName(b)):f.sort==='level'?a.level-b.level:a.speciesId-b.speciesId)*(f.direction==='desc'?-1:1));else if(f.direction==='desc')out.reverse();return out;}
 pageRows(key,rows,size=24){const pages=Math.max(1,Math.ceil(rows.length/size)),page=Math.min(pages,Math.max(1,Math.floor(Number(key==='collection'?this.filters.page:this.pages[key])||1)));if(key==='collection')this.filters.page=page;else this.pages[key]=page;return rows.slice((page-1)*size,page*size);}
 pagination(total,key='collection',size=24){const pages=Math.ceil(total/size);if(pages<=1)return '';const page=key==='collection'?this.filters.page:this.pages[key]??1,indices=pages<=7?Array.from({length:pages},(_,i)=>i+1):[...new Set([1,page-1,page,page+1,pages].filter(n=>n>0&&n<=pages))],item=(n,text=String(n),aria='')=>`<button type="button" class="${page===n?'blue':'gray'}-button compact" data-ui="page" data-scope="${esc(key)}" data-page="${n}" ${aria?`aria-label="${aria}"`:page===n?'aria-current="page"':''}>${text}</button>`;return `<div class="pagination" aria-label="Pages" data-page-scope="${esc(key)}">${pages>7&&page>1?item(page-1,'Previous','Previous page'):''}${indices.map((n,i)=>(i&&n>indices[i-1]+1?'<span aria-hidden="true">…</span>':'')+item(n)).join('')}${pages>7&&page<pages?item(page+1,'Next','Next page'):''}<small class="page-count" role="status">${(page-1)*size+1}–${Math.min(page*size,total)} of ${money(total)}</small></div>`;}
 pagedGrid(key,rows,render){return `<div class="center-card-grid">${this.pageRows(key,rows).map(render).join('')}</div>`+this.pagination(rows.length,key);}
 collection(){const all=this.filterPokemon(this.profile.pokemon),page=Math.min(this.filters.page,Math.max(1,Math.ceil(all.length/24)));this.filters.page=page;const shown=all.slice((page-1)*24,page*24);return this.heading('Your Pokémon',`<small>${all.length} Pokémon</small>`)+this.filterToolbar()+`<div class="actions">${button('Create Trade','ui:create-listing',{},'green')}${routeLink('pickup','Pick Up Pokémon','blue-button')}${routeLink('conversion','Convert Pokémon','gray-button')}</div>`+(shown.length?`<div class="center-card-grid">${shown.map(p=>this.card(p,{actions:button('Trade','ui:create-listing',{uid:p.uid},'green')+button('Nickname','ui:rename-pokemon',{uid:p.uid},'blue')+button('Abandon','ui:abandon',{uid:p.uid},'red')})).join('')}</div>`:blank('No Pokémon found','Try changing your filters.'))+this.pagination(all.length);}
 pickup(){const entries=(this.state.inbox??[]).filter(x=>Number(x.owner)===this.active);return this.heading('Pick Up Pokémon')+`<p>Your completed trades and rewards arrive here. Choose a profile to receive them.</p><div class="toolbar"><label>Send to profile<select id="pickup-target">${this.profileOptions(this.pickupTarget??this.active)}</select></label><div class="actions">${button('Pick Up All','ui:claim',{all:true},'green',entries.length?'':'disabled data-locked="true"')}</div></div>`+(entries.length?`<div class="center-card-grid">${this.pageRows('pickup',entries).map(x=>this.card(x.pokemon,{meta:`${esc(label(x.source??'Reward'))} · ${esc(this.date(x.createdAt))}`,actions:button('Pick Up','ui:claim',{ids:[x.id]},'green')+button('Abandon','ui:abandon-inbox',{ids:[x.id]},'red')})).join('')}</div>`:blank('Nothing to pick up','Completed trades, adoptions, and prizes will appear here.'))+this.pagination(entries.length,'pickup');}
 tradeTabs(current){return this.tabs([['trades','Latest Trades'],['search','Search Trades'],['my-trades','Your Trades'],['offers','Your Offers'],['trainer-adoptions','Trainer Adoptions']],current);}
 listingCard(listing){const own=Number(listing.owner)===this.active;return this.card(listing.pokemon,{meta:`Trainer: ${esc(this.trainer(listing.owner))} · Trade #${esc(listing.id)}<br>${listing.price?`${money(listing.price)} Credits to adopt · `:''}<span class="status-pill ${esc(listing.status)}">${esc(label(listing.status))}</span>`,actions:routeLink('trade/'+listing.id,'View Trade','blue-button')+(own&&listing.status==='open'?button('Edit','ui:edit-listing',{id:listing.id},'green'):'')});}
 trades(page){let rows=this.state.listings??[];if(page==='offers')return this.heading('Your Trade Offers')+this.tradeTabs(page)+this.offersTable((this.state.offers??[]).filter(o=>Number(o.owner)===this.active));if(page==='my-trades')rows=rows.filter(l=>Number(l.owner)===this.active);else rows=rows.filter(l=>l.status==='open');if(page==='search'&&this.filters.query){const q=this.filters.query.toLowerCase();rows=rows.filter(l=>`${l.id} ${this.pokemonName(l.pokemon)} ${this.trainer(l.owner)} ${l.pokemon.speciesId}`.toLowerCase().includes(q));}if(page==='search'&&this.filters.form!=='')rows=rows.filter(l=>(l.pokemon.shiny??0)===Number(this.filters.form));if(page==='search'&&this.filters.type)rows=rows.filter(l=>this.data.species[l.pokemon.speciesId]?.types.includes(this.filters.type));rows=[...rows].sort((a,b)=>page==='search'?(this.filters.sort==='name'?this.pokemonName(a.pokemon).localeCompare(this.pokemonName(b.pokemon)):this.filters.sort==='level'?a.pokemon.level-b.pokemon.level:this.filters.sort==='number'?a.pokemon.speciesId-b.pokemon.speciesId:Number(a.createdAt)-Number(b.createdAt))*(this.filters.direction==='desc'?-1:1):Number(b.createdAt)-Number(a.createdAt));return this.heading(page==='my-trades'?'Your Trades':page==='search'?'Search Trades':'Latest Trades')+this.tradeTabs(page)+(page==='search'?this.filterToolbar():'')+`<div class="actions">${button('Create a Trade','ui:create-listing',{},'green')}${page==='trades'?routeLink('search','Search Pokémon and Trainers','gray-button'):''}</div>`+(rows.length?`<div class="center-card-grid">${this.pageRows(page,rows).map(l=>this.listingCard(l)).join('')}</div>`:blank('No trades found',page==='my-trades'?'Create a listing from one of your Pokémon.':'Listings from the local profiles appear here.'))+this.pagination(rows.length,page);}
 wishlistSummary(groups){if(!groups?.length)return '<p>This trainer will consider any offer.</p>';return groups.map((group,i)=>`<div class="details-box"><strong>${i?'OR: ':''}Looking for all of these Pokémon</strong><ul>${group.map(r=>`<li>${r.shiny<0?'Any appearance':formName({shiny:r.shiny})} ${esc(this.data.species[r.speciesId]?.name??'Pokémon')} · Level ${r.minLevel??1}–${r.maxLevel??100}</li>`).join('')}</ul></div>`).join('');}
 offersTable(offers){const shown=this.pageRows('offers',offers,50),listingsById=new Map();if(offers.length)for(const row of this.state.listings)if(!listingsById.has(row.id))listingsById.set(row.id,row);return (offers.length?`<div class="table-wrap"><table class="center-table"><thead><tr><th>Offer</th><th>Trainer</th><th>Pokémon</th><th>Status</th><th>Actions</th></tr></thead><tbody>${shown.map(o=>{const target=listingsById.get(o.targetId),mine=Number(o.owner)===this.active,canAccept=target&&Number(target.owner)===this.active;return `<tr><td>${routeLink('trade/'+o.targetId,'#'+esc(o.id))}</td><td>${esc(this.trainer(o.owner))}</td><td>${o.listingIds.map(id=>{const p=listingsById.get(id)?.pokemon;return p?esc(this.pokemonName(p)):esc(id);}).join(', ')}</td><td><span class="status-pill ${esc(o.status)}">${esc(label(o.status))}</span></td><td><div class="actions">${o.status==='pending'?(mine?button('Recall Offer','cancelOffer',{id:o.id},'red'):canAccept?button('Accept','ui:accept-offer',{id:o.id},'green')+button('Reject','declineOffer',{id:o.id},'red'):''):routeLink('trade/'+o.targetId,'View trade')}</div></td></tr>`;}).join('')}</tbody></table></div>`:blank('No offers yet','Offers and their status will appear here.'))+this.pagination(offers.length,'offers',50);}
 trade(id){const l=this.state.listings.find(x=>String(x.id)===String(id));if(!l)return this.heading('Trade Not Found')+routeLink('trades','Back to Latest Trades');const own=Number(l.owner)===this.active,offers=this.state.offers.filter(o=>o.targetId===l.id&&(own||Number(o.owner)===this.active));return this.heading('Trade #'+l.id)+this.tradeTabs('')+`<p>Listed by <strong>${esc(this.trainer(l.owner))}</strong> · ${esc(this.date(l.createdAt))} · <span class="status-pill ${esc(l.status)}">${esc(label(l.status))}</span></p><div class="center-card-grid">${this.card(l.pokemon,{meta:`${l.allowHacked?'Tagged Pokémon are allowed in offers.':'Tagged Pokémon are not allowed in offers.'}`,actions:l.status==='open'?(own?button('Edit Trade','ui:edit-listing',{id:l.id},'blue')+button('Recall Pokémon','ui:recall-listing',{id:l.id},'red'):button('Make an Offer','ui:offer',{id:l.id},'green')+(l.price?button(`Adopt for ${money(l.price)} Credits`,'ui:adopt-listing',{id:l.id},'blue'):'')):''})}</div><h2>Trade Requirements</h2>${this.wishlistSummary(l.wishlist)}<p class="muted">An offer that satisfies a complete requirement group is accepted automatically.</p><h2>${own?'Offers Received':'Your Offers'}</h2>${this.offersTable(offers)}`;}
 catalogPokemon(entry){const shiny=entry.shiny??({regular:0,shiny:1,shadow:2}[entry.variant]??0);let moves=(entry.moves??[]).map(m=>typeof m==='number'?m:Object.values(this.data.moves).find(x=>x.name.toLowerCase().replace(/[^a-z0-9]/g,'')===String(m).toLowerCase().replace(/[^a-z0-9]/g,''))?.id).filter(Boolean);if(shiny===2)moves=[368,...moves.filter(v=>v!==368)].slice(0,4);return {uid:'catalog-'+entry.id,speciesId:entry.speciesId,level:entry.level??1,shiny,moves};}
 adoption(page){if(page==='trainer-adoptions'){const rows=(this.state.listings??[]).filter(l=>l.status==='open'&&l.price>0&&Number(l.owner)!==this.active);return this.heading('Trainer Adoptions')+this.tradeTabs(page)+`<p>Adopt a Pokémon listed by another local trainer using your earned Credits.</p>`+(rows.length?`<div class="center-card-grid">${this.pageRows(page,rows).map(l=>this.card(l.pokemon,{meta:`Trainer: ${esc(this.trainer(l.owner))}`,actions:button(`Adopt · ${money(l.price)} Credits`,'ui:adopt-listing',{id:l.id},'green')+routeLink('trade/'+l.id,'View Trade','blue-button')})).join('')}</div>`:blank('No trainer adoptions available','A trainer can set an adoption price when creating a trade.'))+this.pagination(rows.length,page);}const catalog=this.service.catalog?.adoption??[],categories=[...new Set(catalog.map(e=>e.category))],chosen=this.adoptionCategory??categories[0],rows=catalog.filter(e=>e.category===chosen);return this.heading('Adoption Center')+`<p>Spend your earned Credits to adopt a Pokémon. New adoptions wait on the Pick Up Pokémon page.</p><div class="page-tabs">${categories.map(c=>`<button class="${c===chosen?'blue':'gray'}-button compact" data-ui="adoption-category" data-category="${esc(c)}">${esc(label(c))}</button>`).join('')}${routeLink('trainer-adoptions','Trainer Adoptions')}</div><p>Your Credits: <strong>${money(this.wallet.credits)}</strong></p>`+(rows.length?`<div class="center-card-grid">${rows.map(e=>this.card(this.catalogPokemon(e),{actions:button(`Adopt · ${money(e.cost)} Credits`,'ui:adopt',{id:e.id},'green')})).join('')}</div>`:blank('No Pokémon in this category'));}
 daily(){const tiers=Object.values(this.service.catalog?.daily??{}),day=new Date().toISOString().slice(0,10),claimed=this.wallet.dailyDay>=day;return this.heading('Daily Gift')+`<p>Open one Daily Gift each day to win Casino Coins or Credits. The gift price is paid with Pokédollars earned in PTD 1.</p><div class="actions">${button(this.wallet.freeDay>=day?'Daily Credits Collected':'Collect Daily Credits','dailyCredits',{},'green',this.wallet.freeDay>=day?'disabled data-locked="true"':'')}${routeLink('pickup','Pick Up Pokémon','blue-button')}</div><div class="notice">The local daily reward gives 10 Credits and 500 Casino Coins, with extra Credits for newly earned badges.</div><h2>Choose a Daily Gift</h2>${claimed?'<p class="notice">You have opened today’s Daily Gift. Come back tomorrow.</p>':''}<div class="profile-grid">${tiers.map(info=>{const tier=info.id,requirement=info.requirements,unlocked=requirement.type==='none'||requirement.type==='badges'?(this.profile.badges??0)>=(requirement.count??0):(this.profile.completed??[]).includes(30),reason=requirement.type==='none'?'Available to all trainers':requirement.type==='badges'?`Requires ${requirement.count} badges`:`Requires completing ${requirement.name}`;return `<article class="item-tile daily-tier"><div class="item-icon" aria-hidden="true">${tier==='rare'?'★':tier==='uncommon'?'◆':'●'}</div><h3>${esc(info.label)} Gift</h3><p>${esc(reason)}<br><strong>₽ ${money(info.cost)}</strong></p>${button(claimed?'Already Opened':!unlocked?'Locked':'Open '+info.label+' Gift','ui:daily-gift',{tier},'green',claimed||!unlocked?'disabled data-locked="true"':'')}<details><summary>Possible prizes and chances</summary><table class="center-table"><tbody>${info.outcomes.map(r=>`<tr><td>${money(r.amount)} ${this.currencyName(r.currency)}</td><td>${r.percent}%</td></tr>`).join('')}</tbody></table></details></article>`;}).join('')}</div><h2>Mystery Gift</h2><p>Collect a daily shiny Pokémon and a weekly shadow Pokémon, then pick them up into a profile.</p><div class="actions">${button('Daily Mystery Gift','mysteryGift',{kind:'daily'},'blue')}${button('Weekly Mystery Gift','mysteryGift',{kind:'weekly'},'blue')}</div><form data-form="giftCode" class="toolbar"><label>Mystery Code<input name="code" maxlength="100" required autocomplete="off" placeholder="Enter a gift code"></label><button type="submit" class="green-button">Receive Gift</button></form>`;}
 gameCorner(){const catalog=this.service.catalog??{},rewards=catalog.corner??[],slots=catalog.slots??{},grid=this.spinResult?.grid??[['seven','cherry','bar'],['arbok','jiggly','voltorb'],['bar','seven','cherry']],remaining=Math.max(0,(slots.maxSpinsPerDay??50)-(this.wallet.spinsDay===new Date().toISOString().slice(0,10)?this.wallet.spins??0:0));return this.heading('Game Corner')+`<p>Play the nine slot machines with Casino Coins and collect Pokémon prizes. Three matching symbols on a horizontal or diagonal line win.</p><div class="stat-tiles"><div class="stat-tile"><strong>${money(this.wallet.casino)}</strong>Casino Coins</div><div class="stat-tile"><strong>₽ ${money(this.profile.money)}</strong>Pokédollars</div><div class="stat-tile"><strong>${remaining}</strong>Spins remaining today</div></div><form class="toolbar" data-form="exchangeCoins"><label>Pokédollars to exchange<input type="number" name="amount" min="1" max="10000000" step="1" value="100" required><span class="hint">1 Pokédollar = 1 Casino Coin</span></label><button type="submit" class="blue-button">Exchange Coins</button></form><div class="slot-machine ${this.spinning?'spinning':''}" aria-live="polite"><h3>POKÉMON SLOTS</h3><div class="slot-grid">${grid.flatMap((row,y)=>row.map((symbol,x)=>`<div class="slot-reel ${this.spinResult?.wins?.some(w=>w.line.some(([wy,wx])=>wy===y&&wx===x))?'winning':''}">${this.slotSymbol(symbol)}</div>`)).join('')}</div><p class="slot-result">${this.spinResult?this.spinResult.amount?`You won ${money(this.spinResult.amount)} Casino Coins!`:'No winning line. Try another spin!':'Choose a machine and try your luck!'}</p></div><form class="toolbar" data-form="spin"><label>Slot machine<select name="machine">${Array.from({length:slots.machineCount??9},(_,i)=>`<option value="${i+1}" ${this.machine===i+1?'selected':''}>Machine ${i+1}</option>`).join('')}</select></label><button type="submit" class="green-button" ${!remaining?'disabled data-locked="true"':''}>Spin · ${money(slots.spinCost??50)} Coins</button></form><details class="details-box"><summary>Winning symbols</summary><div class="payout-grid">${(slots.payouts??[]).map(r=>`<div>${this.slotSymbol(r.symbol)}<strong>${money(r.amount)} Coins</strong></div>`).join('')}</div><p class="hint">Local machines use equal symbol chances and the same published winning lines and prizes.</p></details><h2>Prize Exchange</h2>`+(rewards.length?`<div class="center-card-grid">${rewards.map(e=>e.kind==='egg'?`<article class="pokemon-card ${e.variant}"><div class="name-tab">${esc(e.name)} Egg</div><div class="card-body"><div class="egg-preview">${this.icon(e.variant==='shadow'?'egg2':'egg1',64)}</div><div><strong>Level 1</strong><p>A random non-evolved ${esc(e.variant)} Pokémon</p></div></div><div class="card-actions">${button(`Get Prize · ${money(e.cost)} Coins`,'ui:buy-reward',{id:e.id},'green')}</div></article>`:this.card(this.catalogPokemon(e),{meta:e.shinyChance?'1% chance of a shiny Pokémon':'',actions:button(`Get Prize · ${money(e.cost)} Coins`,'ui:buy-reward',{id:e.id},'green')})).join('')}</div>`:blank('No prizes available'));}
 conversion(page){const tags=page==='tags',rows=this.filterPokemon(this.profile.pokemon).filter(p=>tags?this.state.tags?.[p.uid]==='hacked'||String(p.myTag??'').toLowerCase()==='h':!p.shiny);return this.heading(tags?'Pokémon Tags':'Shiny / Shadow Pokémon')+this.tabs([['conversion','Shiny / Shadow'],['tags','Remove Tags']],page)+`<p>${tags?'Remove the hacked tag from an eligible Pokémon. Your Pokémon keeps its current appearance.':'Convert a regular Pokémon into its shiny or shadow form. Conversion also removes its hacked tag.'}</p><div class="notice">${tags?'Single Pokémon: 1 Credit or 500,000 Casino Coins. All tagged Pokémon: 10 Credits.':'Shiny: 10 Credits or 750,000 Casino Coins. Shadow: 10 Credits or 1,500,000 Casino Coins.'}</div>${tags?`<div class="actions">${button('Clean All Tags · 10 Credits','ui:clean-all',{},'green')}</div>`:''}${this.filterToolbar()}<div class="center-card-grid">${this.pageRows(page,rows).map(p=>this.card(p,{actions:button(tags?'Remove Tag':'Convert Pokémon','ui:convert',{uid:p.uid,form:tags?'clean':'shiny'},'green')})).join('')}</div>`+this.pagination(rows.length,page);}
 giveaways(page){const mine=page==='my-giveaways',rows=(this.state.giveaways??[]).filter(g=>mine?Number(g.owner)===this.active:page==='past-giveaways'?g.status!=='open':g.status==='open');return this.heading(mine?'Your Giveaways':page==='past-giveaways'?'Concluded Giveaways':'Active Giveaways')+this.tabs([['giveaways','Active Giveaways'],['my-giveaways','Your Giveaways'],['past-giveaways','Concluded Giveaways']],page)+`<div class="actions">${button('Create Giveaway','ui:create-giveaway',{},'green')}${button('Check Giveaway Results','settleGiveaways',{},'blue')}</div>`+(rows.length?`<div class="table-wrap"><table class="center-table"><thead><tr><th>Giveaway</th><th>Trainer</th><th>Prizes</th><th>Ends</th><th>Status</th><th></th></tr></thead><tbody>${this.pageRows(page,rows,50).map(g=>`<tr><td>${esc(g.title)}</td><td>${esc(this.trainer(g.owner))}</td><td>${g.pokemon.length} Pokémon</td><td>${esc(this.date(g.endsAt))}</td><td><span class="status-pill ${esc(g.status)}">${esc(label(g.status))}</span></td><td>${routeLink('giveaway/'+g.id,'View Giveaway','blue-button compact')}</td></tr>`).join('')}</tbody></table></div>`:blank(mine?'You have no giveaways':'No giveaways available','Create a giveaway to share Pokémon with the other local trainers.'))+this.pagination(rows.length,page,50);}
 giveaway(id){const g=this.state.giveaways.find(g=>String(g.id)===String(id));if(!g)return this.heading('Giveaway Not Found')+routeLink('giveaways','Back to Giveaways');const mine=Number(g.owner)===this.active,joined=g.participants.includes(this.active),cancelLeft=Math.max(0,g.createdAt+86400000-(this.service.clock?.()??Date.now())),canCancel=cancelLeft>0;return this.heading(g.title)+`<p>Hosted by <strong>${esc(this.trainer(g.owner))}</strong> · Ends ${esc(this.date(g.endsAt))} · ${g.participants.length} participant${g.participants.length===1?'':'s'}<br>${g.winnerType==='single'?'One winner receives all Pokémon.':'One winner per Pokémon.'}${mine&&g.status==='open'?`<br><span data-giveaway-countdown="${esc(g.id)}">${this.giveawayCountdown(g)}</span>`:''}</p><div class="actions">${g.status==='open'?(mine?(button('Cancel Giveaway','ui:cancel-giveaway',{id:g.id},'red',`data-giveaway-cancel="${esc(g.id)}" ${canCancel?'':'hidden disabled data-locked="true"'}`)):joined?button('Leave Giveaway','leaveGiveaway',{id:g.id},'red'):button('Join Giveaway','joinGiveaway',{id:g.id},'green')):''}${button('Check Results','settleGiveaways',{},'blue')}${routeLink('giveaways','All Giveaways','gray-button')}</div><div class="center-card-grid">${g.pokemon.map(p=>this.card(p)).join('')}</div>${g.status==='ended'?`<h2>Giveaway Results</h2>${g.winners.length?`<ul>${g.winners.map(w=>`<li>${esc(this.trainer(w.owner))} · ${w.pokemonUids.length} Pokémon sent to Pick Up</li>`).join('')}</ul>`:blank('No participants joined','Prizes were returned to the host’s Pick Up page.')}`:''}`;}
 giveawayCountdown(g){const left=Math.max(0,g.createdAt+86400000-(this.service.clock?.()??Date.now()));return left>0?`Cancellation available for ${Math.floor(left/3600000)}h ${Math.ceil(left%3600000/60000)}m.`:'The 24-hour cancellation period has ended.';}
 updateGiveawayCountdown(){if(this.route[0]!=='giveaway'||!this.root?.querySelectorAll)return;for(const node of this.root.querySelectorAll('[data-giveaway-countdown]')){const g=this.state.giveaways.find(g=>String(g.id)===node.dataset.giveawayCountdown);if(!g)continue;const text=this.giveawayCountdown(g);if(node.textContent!==text)node.textContent=text;}for(const node of this.root.querySelectorAll('[data-giveaway-cancel]')){const g=this.state.giveaways.find(g=>String(g.id)===node.dataset.giveawayCancel),available=g?.status==='open'&&g.createdAt+86400000>(this.service.clock?.()??Date.now());if(node.hidden===available)node.hidden=!available;const locked=String(!available);if(node.dataset.locked!==locked)node.dataset.locked=locked;const disabled=this.busy||!available;if(node.disabled!==disabled)node.disabled=disabled;}}
 async tickGiveaway(){if(this.busy)return;this.updateGiveawayCountdown();await this.settleDue();}
 inventory(){const rows=centerInventory(this.profile);return this.heading('Your Items')+`<p>Items recorded in the selected PTD 1 profile. Evolution items are used from a Pokémon’s Items menu in the game.</p><div class="item-grid">${this.pageRows('inventory',rows).map(item=>`<article class="item-tile" data-center-item="${esc(item.key)}"><div class="item-icon" aria-hidden="true">${item.icon?this.icon(item.icon,44):'?'}</div><strong>${esc(item.name)}</strong><span>${item.ownershipKnown?`Owned: ${money(item.count)}`:'Unavailable'}</span><p class="muted" style="margin:8px 0 0">${esc(item.description)}</p></article>`).join('')}</div><div class="actions"><a href="./" class="blue-button">Return to PTD 1</a></div>`+this.pagination(rows.length,'inventory');}
 dex(){const form=this.dexForm??'normal',ids=this.state.dex?.[form]??this.profile.dex?.[form]??[];return this.heading('Pokédex',`<small>${ids.length} / 151 caught</small>`)+`<p>Your account’s collection record across all three profiles. Entries remain after trades, releases and transfers.</p>`+`<div class="page-tabs">${['normal','shiny','shadow'].map(v=>`<button data-ui="dex-form" data-form="${v}" class="${form===v?'blue':'gray'}-button">${label(v)}</button>`).join('')}</div><div class="item-grid">${Array.from({length:151},(_,i)=>i+1).map(id=>{const known=ids.includes(id),p={speciesId:id,shiny:form==='shadow'?2:form==='shiny'?1:0};return `<article class="item-tile">${known?this.sprite(p,64):'<div class="item-icon" aria-hidden="true">?</div>'}<strong>#${String(id).padStart(3,'0')} ${known?esc(this.data.species[id].name):'Unknown'}</strong></article>`;}).join('')}</div>`;}
 notifications(){const rows=(this.state.notifications??[]).filter(n=>Number(n.owner)===this.active).slice().reverse();return this.heading('Notifications')+`<div class="actions">${button('Mark All as Read','readNotifications',{all:true},'blue')}</div>`+(rows.length?this.pageRows('notifications',rows,50).map(n=>`<article class="notification ${n.read?'':'unread'}"><p>${esc(n.text)}</p><small>${esc(this.date(n.createdAt))}</small>${n.route?` · ${routeLink(n.route,'View')}`:''}${!n.read?` · ${button('Mark Read','readNotifications',{ids:[n.id]},'gray')}`:''}</article>`).join(''):blank('No notifications','Trade offers, prizes and giveaway results will appear here.'))+this.pagination(rows.length,'notifications',50);}
 settings(){const s=this.state.settings??{},p=this.profile;return this.heading('Account Settings')+`<p>This local account uses the three profiles saved on your device. No email address or password is required.</p>${p?`<form class="center-form" data-form="renameProfile" id="center-nickname"><label>Trainer Nickname<input name="name" maxlength="30" value="${esc(p.trainer)}" required></label><div><button class="blue-button" type="submit">Save Nickname</button></div></form><h2 style="margin-top:25px" id="center-avatar">Trainer Avatar</h2><form class="center-form" data-form="avatar"><div class="avatar-preview">${this.icon(this.avatarKey(p.avatar),64)}</div><div class="form-columns"><label>Trainer<select name="gender"><option value="boy" ${p.avatar?.gender==='boy'?'selected':''}>Boy</option><option value="girl" ${p.avatar?.gender==='girl'?'selected':''}>Girl</option></select></label><label>Style<select name="style">${this.avatarStyles(p.avatar?.gender,p.avatar?.style)}</select></label></div><div><button class="blue-button" type="submit">Save Avatar</button></div></form>`:''}<h2 style="margin-top:25px">Website Preferences</h2><form class="center-form" data-form="settings"><label class="check-label"><input type="checkbox" name="darkMode" ${s.darkMode?'checked':''}> Dark theme</label><label class="check-label"><input type="checkbox" name="announcements" ${s.announcements!==false?'checked':''}> Show announcements</label><label class="check-label"><input type="checkbox" name="oldCards" ${s.oldCards?'checked':''}> Compact Pokémon cards</label><label class="check-label"><input type="checkbox" name="colorMoves" ${s.colorMoves!==false?'checked':''}> Color move chips by type</label><label class="check-label"><input type="checkbox" name="colorActions" ${s.colorActions!==false?'checked':''}> Color action buttons</label><div class="form-columns"><label>Date format<select name="dateFormat"><option value="MM.DD.YYYY" ${s.dateFormat==='MM.DD.YYYY'?'selected':''}>Month / Day / Year</option><option value="DD.MM.YYYY" ${s.dateFormat==='DD.MM.YYYY'?'selected':''}>Day / Month / Year</option><option value="YYYY.MM.DD" ${s.dateFormat==='YYYY.MM.DD'?'selected':''}>Year / Month / Day</option></select></label><label>Time format<select name="timeFormat"><option value="12" ${s.timeFormat==='12'?'selected':''}>12 hour</option><option value="24" ${s.timeFormat==='24'?'selected':''}>24 hour</option></select></label></div><div><button class="blue-button" type="submit">Save Preferences</button></div></form><h2 style="margin-top:25px" id="center-backup">Local Backup</h2><p>Keep a portable copy of all three profiles and their PokéCenter activity.</p><div class="actions">${button('Export Account Backup','ui:export-bank',{},'green')}${button('Import Account Backup','ui:import-bank',{},'blue')}</div><input type="file" accept="application/json,.json" id="center-import" hidden>`;}
 transfer(){const target=this.transferTarget??2,rows=(this.state.transferVaults?.[target]??[]).filter(v=>Number(v.owner)===this.active);return this.heading('Transfer Pokémon')+`<p>Transfers from PTD 1 are one-way. The chosen Pokémon leave your PTD 1 collection and remain in a local PTD 2 or PTD 3 destination archive.</p><div class="notice">PTD 2 and PTD 3 clients are not included yet. The destination archive preserves your Pokémon until local clients are implemented; its JSON export is a backup record. Export your full account before transferring if you want to keep a copy of your current PTD 1 collection.</div><div class="page-tabs">${[2,3].map(t=>`<button data-ui="transfer-target" data-target="${t}" class="${target===t?'blue':'gray'}-button">PTD ${t} Archive</button>`).join('')}</div><div class="actions">${button('Export Account Backup','ui:export-bank',{},'blue')}${button('Transfer Pokémon to PTD '+target,'ui:transfer',{target},'green')}${button('Export PTD '+target+' Archive','ui:export-vault',{target},'blue')}</div>`+(rows.length?`<div class="center-card-grid">${this.pageRows('transfer-'+target,rows).map(v=>this.card(v.pokemon,{meta:`PTD ${target} destination · ${esc(label(v.gender??'unknown'))} · ${esc(this.date(v.createdAt))}`})).join('')}</div>`:blank('This destination archive is empty','Choose Pokémon from your collection to transfer.'))+this.pagination(rows.length,'transfer-'+target);}
 modal(title,body){for(const key of this.pickers.keys())if(!body.includes(`data-picker="${esc(key)}"`))this.pickers.delete(key);this.dialog.innerHTML=`<div class="dialog-heading"><h2 id="center-dialog-title">${esc(title)}</h2><button type="button" class="dialog-close" data-ui="close" aria-label="Close dialog">×</button></div><div class="dialog-body">${body}<p class="inline-error" role="alert"></p></div>`;if(!this.dialog.open)this.dialog.showModal();this.dialog.querySelector('input:not([type=hidden]),select,button[type=submit]')?.focus();}
 confirm(title,text,type,payload,caption='Confirm',color='green'){this.modal(title,`<p>${esc(text)}</p><div class="actions end"><button class="gray-button" type="button" data-ui="close">Cancel</button>${button(caption,type,payload,color)}</div>`);}
 close(){this.dialog.close();this.pickers.clear();this.dialog.replaceChildren();}
 selectedPokemon(){return this.profile.pokemon.filter(p=>this.selection.has(p.uid));}
 pokemonPicker(name='uids',selected=[],{limit=Infinity}={}){return this.selectionPicker(this.profile.pokemon.map(p=>({id:p.uid,pokemon:p,label:'Select '+this.pokemonName(p)})),{name,selected,limit});}
 selectionPicker(rows,{name,selected=[],limit=Infinity,single=false,options=false}={}){const available=new Set(rows.map(r=>r.id)),chosen=new Set(selected.filter(id=>available.has(id)));this.pickers.set(name,{name,rows,selected:chosen,limit,single,options,page:1,query:''});return `<div data-picker="${esc(name)}">${this.pickerContent(name)}</div>`;}
 pickerContent(name){const picker=this.pickers.get(name),query=picker.query.toLowerCase(),rows=query?picker.rows.filter(row=>`${row.label} ${row.pokemon.speciesId} ${this.pokemonName(row.pokemon)}`.toLowerCase().includes(query)):picker.rows,total=rows.length,pages=Math.max(1,Math.ceil(total/24));picker.page=Math.min(pages,Math.max(1,picker.page));const shown=rows.slice((picker.page-1)*24,picker.page*24),large=picker.rows.length>24,controls=large?`<div class="toolbar picker-toolbar"><label>Find Pokémon<input type="search" data-picker-query value="${esc(picker.query)}" placeholder="Name or Pokédex number"></label><button type="button" class="blue-button" data-ui="picker-filter">Apply</button></div>`:'',key='picker-'+name;this.pages[key]=picker.page;const choices=picker.options?`<label>Pokémon to trade<select name="${esc(name)}" data-picker-choice><option value="" ${!shown.some(row=>picker.selected.has(row.id))?'selected':''}>${picker.selected.size?'Choose on this page to replace your selection':'Choose a Pokémon'}</option>${shown.map(row=>`<option value="${esc(row.id)}" ${picker.selected.has(row.id)?'selected':''}>${esc(row.label)}</option>`).join('')}</select></label>`:`<div class="center-card-grid">${shown.map(row=>this.card(row.pokemon,{extra:`<label class="check-label"><input type="${picker.single?'radio':'checkbox'}" name="${esc(name)}" value="${esc(row.id)}" data-picker-choice ${picker.selected.has(row.id)?'checked':''}> ${esc(row.label)}</label>`})).join('')}</div>`;return controls+(rows.length?choices:blank('No Pokémon found','Try changing your search.'))+this.pagination(total,key)+`${large?'<p class="hint" data-picker-count role="status">'+this.pickerCount(picker)+'</p>':''}`;}
 pickerCount(picker){const selected=[...picker.selected],first=picker.single&&picker.rows.find(row=>row.id===selected[0]);return first?'Selected: '+esc(first.label):`${selected.length} selected${Number.isFinite(picker.limit)?' / '+picker.limit:''} across all pages`;}
 pickerHost(name){return [...this.dialog.querySelectorAll('[data-picker]')].find(node=>node.dataset.picker===name);}
 renderPicker(name){const host=this.pickerHost(name);if(!host)return;host.innerHTML=this.pickerContent(name);host.querySelector('[aria-current="page"], [data-picker-query], [data-picker-choice]')?.focus();}
 filterPicker(name){const picker=this.pickers.get(name),host=this.pickerHost(name);if(!picker||!host)return;picker.query=host.querySelector('[data-picker-query]')?.value??'';picker.page=1;this.renderPicker(name);}
 choosePicker(name,value,checked=true){const picker=this.pickers.get(name);if(!picker||!picker.rows.some(row=>row.id===value))return false;if(!checked){picker.selected.delete(value);return true;}if(picker.single)picker.selected.clear();if(!picker.selected.has(value)&&picker.selected.size>=picker.limit)return false;picker.selected.add(value);return true;}
 pickerValues(form,name){const picker=this.pickers.get(name);return picker&&[...form.querySelectorAll('[data-picker]')].some(node=>node.dataset.picker===name)?[...picker.selected]:null;}
 wishRule(group,index,r={}){return `<div class="wishlist-rule form-columns" data-wish-rule><label>Pokémon<select data-wish="speciesId">${this.speciesOptions(r.speciesId,'Choose a Pokémon')}</select></label><label>Appearance<select data-wish="shiny">${[[-1,'Any appearance'],[0,'Regular'],[1,'Shiny'],[2,'Shadow']].map(([v,t])=>`<option value="${v}" ${Number(r.shiny??-1)===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Minimum level<input type="number" min="1" max="100" data-wish="minLevel" value="${r.minLevel??1}"></label><label>Maximum level<input type="number" min="1" max="100" data-wish="maxLevel" value="${r.maxLevel??100}"></label><button type="button" class="red-button compact" data-ui="remove-wish-rule">Remove requirement</button></div>`;}
 wishGroup(group,rules=[{}]){return `<fieldset class="details-box" data-wish-group><legend>${group?'OR group '+(group+1):'Requirement group 1'}</legend><div data-wish-rules>${rules.map((r,i)=>this.wishRule(group,i,r)).join('')}</div><div class="actions"><button type="button" class="gray-button compact" data-ui="add-wish-rule">Add AND requirement</button><button type="button" class="red-button compact" data-ui="remove-wish-group">Remove group</button></div></fieldset>`;}
 listingDialog(uid,id){const listing=id?this.state.listings.find(l=>l.id===id):null,p=listing?.pokemon??this.profile.pokemon.find(p=>p.uid===(uid??this.selection.values().next().value));if(!listing&&!this.profile.pokemon.length)return this.toast('You need a Pokémon to create a trade.',true);this.modal(listing?'Edit Trade #'+listing.id:'Create a Trade',`<form data-form="${listing?'editListing':'createListing'}" class="center-form">${listing?`<input type="hidden" name="id" value="${esc(listing.id)}">${this.card(listing.pokemon)}`:this.profile.pokemon.length>24?this.selectionPicker(this.profile.pokemon.map(x=>({id:x.uid,pokemon:x,label:`${this.pokemonName(x)} · Level ${x.level} · ${formName(x)}`})),{name:'uid',selected:[p?.uid??this.profile.pokemon[0].uid],single:true,options:true}):`<label>Pokémon to trade<select name="uid" required>${this.profile.pokemon.map(x=>`<option value="${esc(x.uid)}" ${p?.uid===x.uid?'selected':''}>${esc(this.pokemonName(x))} · Level ${x.level} · ${formName(x)}</option>`).join('')}</select></label>`}<label>Instant adoption price (Credits)<input type="number" name="price" value="${listing?.price??0}" min="0" step="1" required><span class="hint">Use 0 to accept trade offers only.</span></label><label class="check-label"><input type="checkbox" name="allowHacked" ${listing?.allowHacked?'checked':''}> Allow Pokémon with a hacked tag</label><div><strong>Auto-accept requirements</strong><p class="hint">A matching offer is accepted automatically. Each group requires all its Pokémon; any complete group is enough. Leave empty to review every offer.</p><div data-wish-groups>${(listing?.wishlist??[]).map((g,i)=>this.wishGroup(i,g)).join('')}</div><button type="button" class="gray-button" data-ui="add-wish-group">Add OR requirement group</button></div><div class="notice">The Pokémon will leave your collection while this listing is open. You can recall an open listing.</div><div class="actions end"><button type="button" class="gray-button" data-ui="close">Cancel</button><button type="submit" class="green-button">${listing?'Save Trade':'Create Trade'}</button></div></form>`);}
 offerDialog(id){const target=this.state.listings.find(l=>l.id===id),choices=this.state.listings.filter(l=>Number(l.owner)===this.active&&l.status==='open'&&l.id!==id);if(!target)return this.toast('This trade is no longer available.',true);this.modal('Make an Offer',`<p>Select up to six Pokémon from <strong>Your Trades</strong> to offer for ${esc(this.pokemonName(target.pokemon))}. A matching auto-accept group completes the trade immediately.</p>${choices.length?`<form data-form="makeOffer"><input name="targetId" type="hidden" value="${esc(id)}">${this.selectionPicker(choices.map(l=>({id:l.id,pokemon:l.pokemon,label:'Offer Trade #'+l.id})),{name:'listingIds',limit:6})}<div class="actions end"><button type="button" class="gray-button" data-ui="close">Cancel</button><button type="submit" class="green-button">Send Offer</button></div></form>`:blank('You have no open trades','Create a trade listing first, then use it in your offer.')+`<div class="actions">${button('Create a Trade','ui:create-listing',{},'green')}</div>`}`);}
 async click(event){const ui=event.target.closest('[data-ui]'),action=event.target.closest('[data-action]');if(ui){event.preventDefault();const key=ui.dataset.ui;if(key==='close')return this.close();if(key==='sidebar'){this.sidebarOpen=!this.sidebarOpen;return this.render();}if(key==='page'){if(this.busy)return;const scope=ui.dataset.scope??'collection',page=Number(ui.dataset.page);if(scope.startsWith('picker-')){const name=scope.slice(7),picker=this.pickers.get(name);if(picker){picker.page=page;this.renderPicker(name);}return;}if(scope==='collection')this.filters.page=page;else this.pages[scope]=page;return this.render();}if(key==='picker-filter'){if(!this.busy)this.filterPicker(ui.closest('[data-picker]').dataset.picker);return;}if(key==='adoption-category'){this.adoptionCategory=ui.dataset.category;return this.render();}if(key==='dex-form'){this.dexForm=ui.dataset.form;return this.render();}if(key==='transfer-target'){this.transferTarget=Number(ui.dataset.target);return this.render();}if(key==='add-wish-group'){const host=this.dialog.querySelector('[data-wish-groups]');if(host.children.length>=6)return this.toast('Use up to six requirement groups.',true);host.insertAdjacentHTML('beforeend',this.wishGroup(host.children.length));return;}if(key==='add-wish-rule'){const host=ui.closest('[data-wish-group]').querySelector('[data-wish-rules]');if(host.children.length>=6)return this.toast('A group can require up to six Pokémon.',true);host.insertAdjacentHTML('beforeend',this.wishRule(0,host.children.length));return;}if(key==='remove-wish-rule'){ui.closest('[data-wish-rule]').remove();return;}if(key==='remove-wish-group'){ui.closest('[data-wish-group]').remove();return;}}
  if(!action||action.disabled||this.busy)return;event.preventDefault();const type=action.dataset.action,p=JSON.parse(action.dataset.payload??'{}');if(type==='readNotifications'&&p.all){p.ids=(this.state.notifications??[]).filter(n=>Number(n.owner)===this.active&&!n.read).map(n=>n.id);delete p.all;}if(!type.startsWith('ui:'))return this.action(type,p,{route:type==='selectProfile'?'home':undefined});
  switch(type.slice(3)){
   case'refresh':this.close();await this.refresh();break;
   case'create-profile':this.modal('Create Profile '+(p.slot+1),`<form data-form="createProfile" class="center-form"><input type="hidden" name="slot" value="${p.slot}"><label>Trainer name<input name="trainer" maxlength="30" value="Satoshi" required></label><div class="form-columns"><label>Game Version<select name="gameVersion"><option value="1">Red Version</option><option value="2">Blue Version</option></select></label><label>Starter Pokémon<select name="starter"><option value="1">Bulbasaur</option><option value="4">Charmander</option><option value="7">Squirtle</option></select></label></div><button type="submit" class="green-button">Create Profile</button></form>`);break;
   case'rename-pokemon':{const pokemon=this.profile.pokemon.find(x=>x.uid===p.uid);this.modal('Give a Nickname',`<form data-form="renamePokemon" class="center-form"><input type="hidden" name="uid" value="${esc(p.uid)}"><label>Nickname<input name="name" maxlength="30" value="${esc(pokemon?.nickname??'')}" placeholder="${esc(this.pokemonName(pokemon))}"><span class="hint">Leave blank to use the species name.</span></label><button type="submit" class="green-button">Save Nickname</button></form>`);break;}
   case'claim':this.action('claim',{ids:p.all?(this.state.inbox??[]).filter(x=>Number(x.owner)===this.active).map(x=>x.id):p.ids,slot:Number(document.querySelector('#pickup-target')?.value??this.active)});break;
   case'abandon-inbox':this.confirm('Abandon Unclaimed Pokémon?','This permanently releases this Pokémon from your Pick Up page.','abandonInbox',p,'Abandon Pokémon','red');break;
   case'daily-gift':{const tier=this.service.catalog.daily[p.tier];this.confirm('Open '+tier.label+' Daily Gift?',`Spend ₽ ${money(tier.cost)} to open your one Daily Gift for today.`,'dailyGift',p,'Open Gift');break;}
   case'abandon':this.confirm('Abandon Pokémon?','This permanently releases the selected Pokémon from your profile.','abandon',p,'Abandon Pokémon','red');break;
   case'create-listing':this.listingDialog(p.uid);break;
   case'edit-listing':this.listingDialog(null,p.id);break;
   case'recall-listing':this.confirm('Recall This Trade?','The Pokémon will return to your Pick Up page and pending offers will be cancelled.','recallListing',p,'Recall Pokémon');break;
   case'offer':this.offerDialog(p.id);break;
   case'accept-offer':this.confirm('Accept This Offer?','Complete the exchange and send the Pokémon to each trainer’s Pick Up page.','acceptOffer',p,'Accept Trade');break;
   case'adopt-listing':{const l=this.state.listings.find(l=>l.id===p.id);this.confirm('Adopt This Pokémon?',`Spend ${money(l?.price)} Credits to adopt this trainer’s Pokémon. It will arrive on your Pick Up page.`,'adoptListing',p,'Adopt Pokémon');break;}
   case'adopt':{const e=this.service.catalog.adoption.find(e=>e.id===p.id);this.confirm('Confirm Adoption',`Spend ${money(e?.cost)} Credits to adopt ${e?.name??'this Pokémon'}. It will arrive on your Pick Up page.`,'adopt',p,'Adopt Pokémon');break;}
   case'buy-reward':{const e=this.service.catalog.corner.find(e=>e.id===p.id);this.confirm('Get This Prize?',`Exchange ${money(e?.cost)} Casino Coins for this prize. It will arrive on your Pick Up page.`,'buyReward',p,'Get Prize');break;}
   case'convert':{const pokemon=this.profile.pokemon.find(x=>x.uid===p.uid);this.modal(p.form==='clean'?'Remove Pokémon Tag':'Convert Pokémon',`<form data-form="convert" class="center-form"><input type="hidden" name="uid" value="${esc(p.uid)}">${this.card(pokemon)}${p.form==='clean'?'<input type="hidden" name="form" value="clean">':'<label>New appearance<select name="form"><option value="shiny">Shiny · 10 Credits / 750,000 Casino Coins</option><option value="shadow">Shadow · 10 Credits / 1,500,000 Casino Coins</option></select></label>'}<label>Pay with<select name="currency"><option value="credits">Credits${p.form==='clean'?' · 1 Credit':''}</option><option value="casino">Casino Coins${p.form==='clean'?' · 500,000 coins':''}</option></select></label><button type="submit" class="green-button">${p.form==='clean'?'Remove Tag':'Convert Pokémon'}</button></form>`);break;}
   case'clean-all':this.confirm('Remove All Hacked Tags?','Spend 10 Credits to clean every tagged Pokémon in the selected profile.','convertAll',{currency:'credits'},'Clean All Tags');break;
   case'create-giveaway':{const ends=new Date(Date.now()+2*86400000),value=new Date(ends.getTime()-ends.getTimezoneOffset()*60000).toISOString().slice(0,16);this.modal('Create a Giveaway',`<form data-form="createGiveaway" class="center-form"><label>Giveaway title<input name="title" maxlength="100" required placeholder="A giveaway for fellow trainers"></label><label>End date and time<input type="datetime-local" name="endsAt" value="${value}" required></label><label>Winner selection<select name="winnerType"><option value="per-pokemon">One winner per Pokémon</option><option value="single">One winner receives all Pokémon</option></select></label><p>Select up to 20 Pokémon. They will be held until the giveaway ends. Choose an end time between 1 and 30 days from now. You can cancel only during the first 24 hours.</p>${this.pokemonPicker('uids',[...this.selection],{limit:20})}<button type="submit" class="green-button">Create Giveaway</button></form>`);break;}
   case'cancel-giveaway':this.confirm('Cancel Giveaway?','End this giveaway and return its unclaimed prizes to your Pick Up page.','cancelGiveaway',p,'Cancel Giveaway','red');break;
   case'transfer':this.modal('Transfer to PTD '+p.target,`<form data-form="transfer" class="center-form"><input type="hidden" name="target" value="${p.target}"><label>Gender for transferred Pokémon<select name="gender"><option value="male">Male</option><option value="female">Female</option><option value="genderless">Genderless</option></select></label><p>This is a one-way transfer. The chosen Pokémon leave your PTD 1 collection and enter your local PTD ${p.target} destination archive. Export your account first to keep a copy of your current collection.</p>${button('Export Account Before Transfer','ui:export-bank',{},'blue')}${this.pokemonPicker('uids',[...this.selection])}<button type="submit" class="green-button">Confirm One-Way Transfer</button></form>`);break;
   case'export-vault':this.download({version:1,game:p.target,records:(this.state.transferVaults[p.target]??[]).filter(v=>Number(v.owner)===this.active)},`ptd${p.target}-destination-archive.json`);break;
   case'export-bank':this.download(this.bank,'ptd-pokecenter-account.json');break;
   case'import-bank':document.querySelector('#center-import').click();break;
  }
 }
 async submit(event){const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();if(this.busy||!form.reportValidity())return;const type=form.dataset.form,fields=new FormData(form);if(type==='filter'){this.filters={...this.filters,...Object.fromEntries(fields),page:1};this.selection.clear();this.pages={};return this.render();}const payload=Object.fromEntries(fields);
  for(const key of ['slot','starter','gameVersion','style','price','machine','amount','target'])if(payload[key]!==undefined)payload[key]=Number(payload[key]);if(type==='avatar'&&payload.gender==='girl'&&[9,12,15].includes(payload.style))payload.gender='boy';
  for(const key of ['allowHacked','darkMode','announcements','oldCards','colorMoves','colorActions'])if(form.elements.namedItem(key))payload[key]=form.elements.namedItem(key).checked;
  for(const key of ['uids','listingIds']){const selected=this.pickerValues(form,key);if(selected)payload[key]=selected;else if(form.querySelector(`[name="${key}"]`))payload[key]=fields.getAll(key);}const chosenUid=this.pickerValues(form,'uid');if(chosenUid)payload.uid=chosenUid[0];
  if(type==='createListing'||type==='editListing'){payload.wishlist=[...form.querySelectorAll('[data-wish-group]')].map(group=>[...group.querySelectorAll('[data-wish-rule]')].map(rule=>Object.fromEntries([...rule.querySelectorAll('[data-wish]')].map(input=>[input.dataset.wish,Number(input.value)]))).filter(r=>r.speciesId)).filter(g=>g.length);}
  if(type==='createGiveaway'){payload.endsAt=new Date(payload.endsAt).getTime();if(payload.uids?.length>20)return this.toast('Choose at most 20 giveaway Pokémon.',true);}
  if(['createGiveaway','transfer'].includes(type)&&!payload.uids?.length)return this.toast('Select at least one Pokémon.',true);
  if(type==='makeOffer'&&(!payload.listingIds?.length||payload.listingIds.length>6))return this.toast('Select one to six of your trade listings.',true);
  if(type==='spin'){this.machine=payload.machine;this.spinning=true;this.render();const result=await this.action(type,payload);this.spinning=false;if(result)this.spinResult=result;this.render();return;}
  const result=await this.action(type,payload,{route:type==='createProfile'?'home':type==='createListing'?'my-trades':type==='createGiveaway'?'my-giveaways':undefined});if(type==='makeOffer'&&result?.autoAccepted)this.toast('Your offer matched the trade requirements. The exchange is complete.');
 }
 async change(event){const target=event.target;if(target.matches('[data-picker-choice]')&&target.value){const host=target.closest('[data-picker]'),name=host.dataset.picker,picker=this.pickers.get(name),accepted=this.choosePicker(name,target.value,target.tagName==='SELECT'||target.checked);if(!accepted){target.checked=false;this.toast(`Choose at most ${picker.limit} Pokémon.`,true);}const count=host.querySelector('[data-picker-count]');if(count)count.innerHTML=this.pickerCount(picker);}if(target.name==='uids'&&target.closest('form[data-form="createGiveaway"]')?.querySelectorAll('[name="uids"]:checked').length>20){target.checked=false;this.toast('A giveaway can include up to 20 Pokémon.',true);}if(target.closest('form[data-form="avatar"]')){const form=target.closest('form'),gender=form.elements.gender.value;if(target.name==='gender')form.elements.style.innerHTML=this.avatarStyles(gender,1);form.querySelector('.avatar-preview').innerHTML=this.icon(this.avatarKey({gender,style:Number(form.elements.style.value)}),64);}if(target.matches('#pickup-target'))this.pickupTarget=Number(target.value);if(target.matches('[data-select-pokemon]')){target.checked?this.selection.add(target.dataset.selectPokemon):this.selection.delete(target.dataset.selectPokemon);target.closest('.pokemon-card').classList.toggle('card-selected',target.checked);}if(target.name==='listingIds'&&this.dialog.querySelectorAll('[name="listingIds"]:checked').length>6){target.checked=false;this.toast('You can offer up to six trade listings.',true);}if(target.matches('#center-import')){const file=target.files?.[0];if(!file)return;try{const bank=JSON.parse(await file.text());this.pendingImport=bank;this.modal('Import PokéCenter Account?',`<p>This replaces the local account, its three profiles, and PokéCenter activity. Export your current account first if you want to keep a copy.</p><div class="actions">${button('Export Current Account','ui:export-bank',{},'blue')}${button('Replace Local Account','ui:confirm-import',{},'red')}</div>`);const confirm=this.dialog.querySelector('[data-action="ui:confirm-import"]');confirm.onclick=event=>{event.stopPropagation();this.action('importBank',{bank:this.pendingImport},{route:'home'});};}catch(error){this.toast('The selected file is not a valid JSON backup.',true);}target.value='';}}
 download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);this.toast('Your backup has been exported.');}
}
